/**
 * `BlockStripping.java`: the `msm:strippable` half of the runtime's `BlockExtras` (ADR 0067 D3,
 * D4, D10; Minecraft 26.3, Mojang names) as a plain helper: one Fabric `UseBlockCallback` that
 * strips the project's blocks with any item whose `minecraft:block_transformer` names
 * `minecraft:axe`, copying every shared property (the axis of a log), playing the strip sound,
 * damaging the item by 1 and swinging, as vanilla's axe. Vanilla stripping is a data registry
 * entry a data pack can only replace whole, and Fabric API has no strippable registry any more.
 *
 * @packageDocumentation
 */

/**
 * The source of `<package>/BlockStripping.java`.
 *
 * @param javaPackage - The mod's Java package.
 */
export function blockStrippingJava(javaPackage: string): string {
  return `// Generated by MCSuperMods: msm:strippable of msm_runtime (BlockExtras) as a plain helper.
package ${javaPackage};

import java.util.IdentityHashMap;
import java.util.Map;
import net.fabricmc.fabric.api.event.player.UseBlockCallback;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Holder;
import net.minecraft.core.component.BlockTransformer;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.Property;
import net.minecraft.world.level.gameevent.GameEvent;
import net.minecraft.world.phys.BlockHitResult;

/**
 * msm:strippable: an axe strips a block into another. Vanilla stripping is the {@code block_transformer} registry entry
 * {@code minecraft:axe}, which a data pack can only replace whole, so this callback strips the mod's blocks before the
 * item's own transformer runs. Dispensers and other mods that call the transformer directly do not see these blocks.
 */
public final class BlockStripping {
    /** The {@code block_transformer} entry that marks an axe: vanilla axes, the mod's axes and other mods' axes. */
    public static final Identifier AXE_TRANSFORMER = Identifier.withDefaultNamespace("axe");

    /** Block to the id of the block it strips into; resolved on use, so the target may register later. */
    private static final Map<Block, Identifier> STRIPPABLE = new IdentityHashMap<>();
    private static boolean installed;

    private BlockStripping() {}

    /** Makes {@code block} strip into the block {@code into}; called once per block at start-up. */
    public static void add(Block block, Identifier into) {
        STRIPPABLE.put(block, into);
    }

    /** Installs the stripping callback, once. */
    public static void register() {
        if (!installed) {
            installed = true;
            UseBlockCallback.EVENT.register(BlockStripping::strip);
        }
    }

    /**
     * Vanilla's axe rule ({@code BlockTransformer.transformBlock}): a main-hand use with a blocking item (a shield) in the
     * off hand passes unless the player sneaks; otherwise the block turns into its target with every shared property
     * copied (the axis of a log), the strip sound plays, the item takes 1 damage and the hand swings (a success). The
     * client predicts the same answer; only the server changes the world. An unknown target passes.
     */
    private static InteractionResult strip(Player player, Level level, InteractionHand hand, BlockHitResult hit) {
        if (player.isSpectator()) {
            return InteractionResult.PASS;
        }
        BlockPos pos = hit.getBlockPos();
        BlockState state = level.getBlockState(pos);
        Identifier into = STRIPPABLE.get(state.getBlock());
        if (into == null) {
            return InteractionResult.PASS;
        }
        ItemStack stack = player.getItemInHand(hand);
        Holder<BlockTransformer> transformer = stack.get(DataComponents.BLOCK_TRANSFORMER);
        if (transformer == null || !transformer.is(AXE_TRANSFORMER)) {
            return InteractionResult.PASS;
        }
        if (hand == InteractionHand.MAIN_HAND && player.getOffhandItem().has(DataComponents.BLOCKS_ATTACKS)
                && !player.isSecondaryUseActive()) {
            return InteractionResult.PASS;
        }
        if (!BuiltInRegistries.BLOCK.containsKey(into)) {
            return InteractionResult.PASS;
        }
        BlockState stripped = copyProperties(state, BuiltInRegistries.BLOCK.getValue(into).defaultBlockState());
        if (!level.isClientSide()) {
            level.setBlock(pos, stripped, Block.UPDATE_ALL_IMMEDIATE);
            level.playSound(null, pos, SoundEvents.AXE_STRIP.value(), SoundSource.BLOCKS, 1.0f, 1.0f);
            level.gameEvent(GameEvent.BLOCK_CHANGE, pos, GameEvent.Context.of(player, stripped));
            stack.hurtAndBreak(1, player, hand.asEquipmentSlot());
        }
        return InteractionResult.SUCCESS;
    }

    /** {@code to} with every property it shares with {@code from} (the same {@code Property}, such as the axis) set to {@code from}'s value. */
    private static BlockState copyProperties(BlockState from, BlockState to) {
        BlockState out = to;
        for (Property<?> property : from.getProperties()) {
            if (to.hasProperty(property)) {
                out = copy(from, out, property);
            }
        }
        return out;
    }

    private static <T extends Comparable<T>> BlockState copy(BlockState from, BlockState to, Property<T> property) {
        return to.setValue(property, from.getValue(property));
    }
}
`;
}
